pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, address(this).balance);
        vm.assume(amount > 0); // deposit must be positive to show difference
        uint256 senderBalBefore = address(this).balance;
        c.deposit{value: amount}();
        uint256 senderBalAfter = address(this).balance;
        // For the reference C, sender's balance decreases by exactly amount (deposit adds to contract)
        // The buggy version subtracts from balances but still transfers msg.value, so sender balance decreases by amount
        // So this rule does not differentiate. Instead, check that total supply (balances[msg.sender] + contract balance - sum of deposits) is invariant.
        // Since we cannot read balances directly, use the contract's total ether.
        uint256 contractBalAfter = address(c).balance;
        // For reference: contract balance increases by amount, sender decreases by amount
        // For buggy: contract balance increases by amount, but balances[msg.sender] decreases instead of increasing
        // So after buggy deposit, balances[msg.sender] = 0 - amount (underflows, but assert prevents) or negative? Actually the assert check passes if balances[msg.sender] + msg.value > balances[msg.sender], which is true for any positive msg.value. But the subtraction underflows unless balances[msg.sender] >= msg.value. However, msg.sender may have no prior deposit, so balances[msg.sender] = 0, and 0 - amount underflows to a huge number. So after buggy deposit, balances[msg.sender] becomes a huge number. The sum of balances of all senders is huge, while contract balance only increased by amount. The invariant that total ether = contract balance + sum of balances no longer holds. But we can't read balances. Instead, we can test that after deposit, the sender can withdraw up to what he deposited. For reference, after one deposit of amount, sender can withdraw amount. For buggy, after one deposit of amount, sender can withdraw a huge amount (underflowed balance). So use withdraw to check.
        // But the test must end with one assertTrue. We'll check that after deposit, immediate withdraw of amount succeeds for reference, but for buggy it will also succeed because balance is huge. That's not a good differentiator.
        // Alternative: check that the sum of all withdrawals possible equals total deposits. For a single user, after a deposit, the user should be able to withdraw exactly the amount deposited. But in buggy, after deposit, balance is underflowed huge, so withdraw of amount succeeds, but then balance is still huge. So not different.
        // The only simple rule that holds for reference but fails for buggy is: after deposit, the contract's total ether balance equals the amount deposited (assuming initial balance 0). But we can't assume initial balance 0 because set up might have sent ether. So we need a precondition.
        // Let's go with: If the sender's initial balance in the contract is 0, then after a deposit of amount, the sender's balance (via a getter? none) is exactly amount. Since no getter, we use the refund function to retrieve all balance. After deposit, call refund() and check sender receives the deposited amount. For reference, refund() sends the exact balance and sets balance to 0. For buggy, after deposit, refund() will try to send the huge underflowed balance, which will likely revert due to insufficient contract balance. So we can assert that refund() succeeds for reference but fails for buggy? But we need a general rule that is true for reference and false for buggy.
        // Rule: After a deposit, calling refund() does not revert. In reference, refund() always succeeds because the contract has exactly the sender's balance. In buggy, refund() may revert if the underflowed balance exceeds contract balance (which it will after one deposit, because contract balance = amount, but requested transfer = huge underflowed amount). So assertTrue(tryRefundSucceeds).
        bool refundSuccess;
        (bool success, ) = address(c).call(abi.encodeWithSignature("refund()"));
        refundSuccess = success;
        assertTrue(refundSuccess, "Refund should succeed after a deposit");
    }
}

