pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address to, uint256 depositAmount) public {
        vm.assume(caller != address(0) && to != address(0) && depositAmount > 0 && depositAmount <= 1e30);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        // After deposit, check that migrateTo can only be called by creator
        // We simulate what happens if caller tries to migrate
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("migrateTo(address)", to));
        // The reference contract: migrateTo should revert if caller != creator.
        // The buggy contract: migrateTo reverts if caller == creator.
        // So the correct behavior is: success should be false when caller != creator.
        // But we need a general rule that holds for all inputs.
        // The rule: if caller is not the creator, migrateTo should fail (revert).
        // Since in setUp, creator = address(this), and caller is a fuzz address,
        // caller will never be the creator (msg.sender in constructor is address(this)).
        // Therefore, in the reference, migrateTo should always revert.
        // In the buggy version, it should succeed when caller != creator (since condition is creator != msg.sender).
        assertTrue(!success, "migrateTo should revert for non-creator");
    }
}

