import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(c).balance / 2);
        uint256 initialBalance = address(c).balance;
        address payable to = payable(address(0x1234));
        uint256 toInitialBalance = to.balance;
        vm.deal(address(c), amount * 2);
        c.deposit{value: amount}();
        c.migrateTo(to);
        assertTrue(to.balance == toInitialBalance + initialBalance + amount);
    }
}

