pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address to, uint256 depositAmount) public {
        // Restrict depositAmount so it doesn't overflow
        vm.assume(depositAmount <= type(uint256).max - address(c).balance);
        // Fund the test contract to send as deposit
        vm.deal(address(this), depositAmount);
        // Deposit
        c.deposit{value: depositAmount}();
        // Record balance before migrateTo
        uint256 balanceBefore = address(c).balance;
        // Call migrateTo as creator (the deployer is the creator)
        c.migrateTo(to);
        uint256 balanceAfter = address(c).balance;
        // The rule: after deposit, migrateTo should send the full balance, so contract balance becomes zero
        assertTrue(balanceAfter == 0);
    }
}

