pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.assume(amount < type(uint256).max / 2); // avoid overflow in deposit
        vm.deal(sender, amount * 2);

        // Deposit so sender has balance
        vm.prank(sender);
        c.deposit{value: amount}();

        uint256 balanceBefore = address(c).balance;

        // Withdraw the same amount
        vm.prank(sender);
        c.withdraw(amount);

        // After withdraw, contract balance should decrease by exactly amount
        assertTrue(address(c).balance == balanceBefore - amount);
    }
}
